+    });
+
+    test('bindings with identical identity fields are equal across '
+        'provenance (I5 round-trip)', () {
+      final a = ProviderModelBinding.resolve(
+        providerKind: 'kimi',
+        modelId: 'kimi-k2',
+        recordName: 'kimi',
+        provenance: BindingProvenance.restore,
