+    if (endpointSpec.defaultBaseUrl.isEmpty) continue;
+    if (!sameEndpoint(endpointSpec.defaultBaseUrl, baseUrl)) continue;
+    if (endpointSpec.api == spec.api) return;
+    throw ConfigException(
