}) {
  if (kind != 'openai-completions' &&
      kind != 'anthropic' &&
      kind != 'google' &&
      kind != 'dial' &&
      kind != 'minimax' &&
      kind != 'zai' &&
      kind != 'aiin' &&
      kind != 'chatgpt-codex' &&
      kind != 'copilot') {
    throw ConfigException('Unknown provider kind: $kind');
