    ring = ApiKeyRing(
      baseName: '',
      credentials: const [ApiKeyCredential('', '')],
    );
  } else {
    final keyBase = _keyBaseName(ref, spec);
    if (keyBase == null) {
      skipped.add(
        '${ref.label} (missing API key: ${_missingKeyHint(ref, spec)})',
