  String? baseUrl,
  Iterable<String>? scopedKeyNames,
  Map<String, String>? env,
  String? pinnedKeyName,
}) {
  final key = optionalProviderApiKey(
    provider,
    keys,
    baseUrl: baseUrl,
    scopedKeyNames: scopedKeyNames,
    env: env,

